INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1016, 'Nhà trẻ Thiên Ân Cần Thơ &#8211; Chuyến đi từ thiện ý nghĩa của tôi', 'chuyen-tu-thien-nha-tre-thien-an', '<p><strong>Nhà trẻ Thiên Ân</strong> hay còn gọi cái tên thân thương khác là Mái ấm Thiên Ân. Đúng như cái tên mái ấm của mình. Nơi đây là nơi nuôi dưỡng ấm áp cho các trẻ mồ côi hoặc những đứa bé có gia đình khó khăn không nuôi nổi. Nơi đây đã mang lại cho các em có hoàn cảnh bất hạnh một mái ấm gia đình. Không những vậy, nơi đây còn nuôi dạy cho các em đến trường và xin việc làm. Tôi đã có dịp đến thăm mái ấm Thiên Ân một vài lần. Những chuyến đi đều mang hương vị thân thương với những đứa bé ở đây. Mỗi lần đến cách vài tháng hay có khi cả năm. Những đứa bé dần trở nên lớn hơn. Đôi khi những đứa bé mình từng dỗ dành khóc nhè nay đã lớn. Nhưng nụ cười của chúng ở trên môi luôn làm tôi cảm động.</p>
<h2>Nhà Trẻ Thiên Ân</h2>
<p>Địa chỉ: 601/22 KV Bình Trung, P.Long Hòa, Q. Bình Thủy, TP. Cần Thơ.</p>
<p>Số điện thoại:&nbsp;0292888542</p>
<p><iframe style="border: 0;" src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3928.6337853049245!2d105.73561171428231!3d10.047047774980342!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31a0887d1f13574d%3A0x64a61ace4ec9e78!2sThien+An+Orphanage!5e0!3m2!1svi!2s!4v1540479889639" width="600" height="450" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h3>Nhà của những đứa trẻ đáng thương</h3>
<p>Nhà trẻ Thiên Ân ở Cần Thơ được thành lập vào năm 2004. Đây là nơi chăm sóc các bé nhỏ, thanh thiếu niên có hoàn cảnh khó khăn. Những đứa trẻ bị bỏ rơi khi vừa sinh ra hay những gia đình nghèo khó không đủ khả năng nuôi con của mình. Những đứa bé ở đây thường dao động từ 30-50 bé từ 3 đến 18 tuổi. Ở đây đủ mọi vùng miền khác nhau, bạn sẽ bắt gặp những đứa bé bập bẹ những tiếng dân tộc khác. Chúng có thể là người Chăm, Khmer hay Kinh. Tất cả đều có một thân thế đau buồn.</p>
<p><figure id="attachment_1020" aria-describedby="caption-attachment-1020" style="width: 600px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1020" src="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho4.jpg" alt="Nhà Trẻ Thiên Ân Cần Thơ" width="600" height="398" srcset="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho4.jpg 960w, https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho4-768x510.jpg 768w" sizes="(max-width: 600px) 100vw, 600px" /><figcaption id="caption-attachment-1020" class="wp-caption-text">Nhà Trẻ Thiên Ân Cần Thơ</figcaption></figure></p>
<p>Nơi đây thỉnh thoảng vẫn tổ chức những buổi dạy thêm cho các bé từ anh văn đến tin học. Nhưng đa phần đều do tình nguyện viên là sinh viên, một số người hảo tâm hay người nước ngoại dạy miễn phí. Nên đôi khi các khóa học thường không được nối liền mạch. Hy vọng nơi đây sẽ có những tình nguyện viên gắn bó lâu dài hơn.</p>
<h3>Chuyến đi thăm của tôi đến mái ấm Thiên Ân</h3>
<p><figure id="attachment_1018" aria-describedby="caption-attachment-1018" style="width: 600px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1018" src="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho2.jpg" alt="Nhà Trẻ Thiên Ân Cần Thơ" width="600" height="450" srcset="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho2.jpg 800w, https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho2-768x576.jpg 768w" sizes="(max-width: 600px) 100vw, 600px" /><figcaption id="caption-attachment-1018" class="wp-caption-text">Nhà Trẻ Thiên Ân Cần Thơ</figcaption></figure></p>
<p>Ngay từ ban đầu khi có người hỏi tôi muốn thăm một nhà trẻ mồ côi không? Tôi đã nhận lời ngay lập tức. Những đứa trẻ khi sinh ra đều là những thiên thần. Và tôi sẽ không bỏ lỡ chuyến thăm đến nơi mà các thiên thần cần tôi. Tôi hỏi người bạn khác tại sao muốn đến đó vậy? Không phải nó hơi xa trung tâm thành phố Cần Thơ? &#8220;Chúng ta cần đem lại điều tốt đẹp nhất cho người cần chúng ta nhất! Mà 10km từ trung tâm thành phố thì quá ngắn!&#8221;.</p>
<p>Khi ấy chúng tôi dùng xe máy chạy vào trong con hẻm dưới một cây cầu. Chạy một con đường làng không lớn nhưng trải xi măng kéo dài. Lúc ấy, cầu bắc ngang Nhà trẻ Thiên Ân vẫn còn độc mộc như một cây cầu khỉ cỡ to vậy. Tay láy của tôi khá cứng nên cứ băng băng đi qua. Những bạn nữ chạy phía sau cứ la hét thất thanh. Còn bây giờ, đường vào Nhà trẻ đã được xây dựng lại khá ổn. Những nhà hảo tâm và chính quyền nơi đây đã tạo điều kiện tốt hơn cho mái ấm và người dân của phường.</p>
<p><figure id="attachment_1021" aria-describedby="caption-attachment-1021" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1021" src="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho3.jpg" alt="Nhà Trẻ Thiên Ân Cần Thơ" width="960" height="637" srcset="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho3.jpg 960w, https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho3-768x510.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1021" class="wp-caption-text">Nhà Trẻ Thiên Ân Cần Thơ</figcaption></figure></p>
<h3>Sự khởi đầu ở nhà trẻ Cần Thơ</h3>
<p>Đứng trước cổng nhỏ của ngôi nhà. Sân vườn nơi đây khá thoáng mát, có một số dụng cụ trò chơi được quyên tặng để lác đác trong sân. Tôi dừng xe lại và cùng đoàn đem quà vào nhưng cổng đã khóa lại. Một bé gái dễ thương chạy ra lễ phép hỏi:</p>
<p>&#8211; Mấy anh tìm ai ạ?</p>
<p>Tôi mỉm cười thân thiện. Sách vở vẫn hay nói 5 giây đầu tiên khi tiếp xúc rất là quan trọng. Tôi nói từ tốn:</p>
<p>&#8211; Tụi anh hôm trước có gọi cho cô. Anh đến để đem quà tặng cho mấy đứa nè. Em vào hỏi cô rồi mở cửa cho tụi anh vào với!</p>
<p>Sau khi thông báo cho cô phụ trách, đứa bé chạy ra mở cửa và khoanh tay chào tôi lễ phép. Cô phụ trách rất thân thiện, giới thiệu cho chúng tôi về Nhà trẻ Thiên Ân. Chúng tôi nhanh chóng chia người ra, chuẩn bị kế hoạch đầy đủ. Một nhóm thì chuẩn bị các quà tặng và chương trình phía sau. Một nhóm thì cùng chơi với mấy đứa trẻ.</p>
<p><figure id="attachment_1017" aria-describedby="caption-attachment-1017" style="width: 370px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1017 size-medium" src="https://media.huynhhieutravel.com/nha-tre-thien-an-can-tho-370x260.jpg" alt="Nhà Trẻ Thiên Ân Cần Thơ" width="370" height="260"><figcaption id="caption-attachment-1017" class="wp-caption-text">Nhà Trẻ Thiên Ân Cần Thơ</figcaption></figure></p>
<p>Tôi cứ mải miết chơi với mấy đứa trẻ vì chúng quá dễ thương và ngoan. Chúng rất thích bu lấy người lớn và chơi đủ trò nhưng lại rất nghe lời. Sự ngây thơ và hồn nhiền của chúng đã cải tạo tâm hồn tưởng chừng già nua của tôi. Sau khi chúng tôi chơi đủ mệt với những đứa bé. Chương trình tiếp tục với những phần quà trao tặng.</p>
<h3>Và tôi đã khóc&#8230;</h3>
<p>Khi tôi đang chơi với những đứa trẻ. Chúng tôi chơi trò chuyền vật và hát. Những đứa trẻ rất hứng thú với trò chơi, chúng chuyền đồ rất nhanh. Bỗng một đứa trẻ nhỏ tuổi òa khóc. Chúng tôi rất bất ngờ, vội quây lấy đứa bé. Tôi ẳm đứa bé lên và dỗ dành nó. Nhưng nó vẫn cứ khóc. Nó khóc lớn, mắt đỏ hoe cả lên nhưng không nói tại sao khóc. Tôi đem kẹo bánh dỗ nhưng nó chỉ cầm mà không ăn hay nín khóc. Một đứa trẻ lớn hơn nói lớn: &#8220;Nó lại nhớ mẹ nó mà khóc đấy!&#8221;.</p>
<p>Đứa bé thút thít, nấc nghẹn lên tiếng: &#8220;Con không cần gì hết, con cần mẹ con à!&#8221;. Nhìn vào đôi mắt to tròn đẫm lệ của nó, mắt tôi cũng dần đỏ hoe. Cha, mẹ &#8211; Những điều linh thiêng nhất mà đa số chúng ta đều có. Đôi khi chúng ta cũng không quá đủ trân trọng thứ ấy. Nhưng đứa bé này, à không, tất cả những đứa bé này đều thiếu nó.</p>
<p>Tôi đưa đứa bé lại cho người khác ẩm, đứa bé đã nín khóc. Nhưng tôi đã bỏ đi ra sau nhà, có lẽ nước mắt thật dễ lây cho nhau.</p>
<p><figure id="attachment_2573" aria-describedby="caption-attachment-2573" style="width: 680px" class="wp-caption alignleft"><img loading="lazy" decoding="async" class="wp-image-2573" src="https://media.huynhhieutravel.com/một-em-bé-dễ-thương-ở-nhà-trẻ-Thiên-Ân.jpg" alt="Một em bé dễ thương ở nhà trẻ Thiên Ân" width="680" height="451" srcset="https://media.huynhhieutravel.com/một-em-bé-dễ-thương-ở-nhà-trẻ-Thiên-Ân.jpg 960w, https://media.huynhhieutravel.com/một-em-bé-dễ-thương-ở-nhà-trẻ-Thiên-Ân-768x509.jpg 768w" sizes="(max-width: 680px) 100vw, 680px" /><figcaption id="caption-attachment-2573" class="wp-caption-text">Một em bé dễ thương ở nhà trẻ Thiên Ân</figcaption></figure></p>
<h3>Câu chuyện của những đứa trẻ ngoan bị bỏ rơi</h3>
<p>Tôi ngập ngừng khi gặp cô phụ trách. Tôi không mở miệng được vì ngại hỏi. Dường như hiểu được ánh mắt và cử chỉ của tôi. Cô phụ trách nhẹ cười và nói:</p>
<p>&#8211; Có phải con muốn hỏi những đứa trẻ ở đây đều không có cha mẹ đúng không? Cũng không hẳn tất cả đều không có cha mẹ. Những đứa trẻ ở đây cũng có những đứa bị bỏ rơi. Chúng bị bỏ rơi từ nhỏ, vì cha mẹ chúng có người vì &#8220;lỡ&#8221; có chúng khi còn nhỏ hoặc có người nuôi không nổi phải bỏ lại đây. Ở đây có những đứa vẫn chưa biết tiếng Kinh nữa đó con. Nhưng Thiên Ân đã thu nhận tất cả chúng lại, chăm sóc những đứa bé này, dạy chúng học. Chúng rất chăm ngoan lại thông minh nữa. Hy vọng 10,20 năm sau chúng sẽ thành những người giúp ích cho xã hội.</p>
<p>Tôi ngập ngừng hỏi tiếp:</p>
<p>&#8211; Nuôi chúng khó khăn không cô?</p>
<p>Cô dịu dàng trả lời:</p>
<p>&#8211; À! Khó chứ con. Một đứa trẻ thôi đã nuôi vất vả lắm rồi. Cô có tới mấy chuc đứa làm sao không khó được. Nhưng chúng ta chỉ cần cái tâm của mình, những cái khó sẽ được giải quyết thôi. Ở đây các cô chia nhau chăm sóc những đứa trẻ này. Dạy chúng đôi khi nghiêm khắc nhưng chúng cũng rất ngoan. Kinh phí nuôi dạy chúng thì có những nhà hảo tâm và nhà nước giúp đỡ thêm. Cô làm được việc này cũng là nhờ những người như nhóm của con vậy.</p>
<p>Tôi thật sự khâm phục cô và yêu những đứa trẻ này khi biết rõ hơn về thân thế của chúng.</p>
<p>Nếu bạn ở Cần Thơ, những đóng góp của bạn về vật chất hay góp sức thăm những đứa bé này đều là những san sẻ tuyệt vời. Sau những lần thăm nơi đây, tôi đều cảm thấy được dung dưỡng và thanh lọc hơn. Tôi hy vọng các bạn cũng sẽ chia sẽ tình thương của mình với nơi đây. Hy vọng Mái ấm Thiên Ân sẽ ngày càng phát triển. Nơi đây sẽ trở thành ngôi nhà, gia đình của những đứa trẻ cơ nhở mồ côi, thiếu may mắn trong cuộc sống.</p>
', 'Nhà trẻ Thiên Ân hay còn gọi cái tên thân thương khác là Mái ấm Thiên Ân. Đúng như cái tên mái ấm của mình. Nơi đây là nơi nuôi dưỡng ấm áp cho các trẻ mồ côi hoặc những đứa bé có gia đình khó khăn không nuôi nổi. Nơi đây đã mang lại [&hellip;]', 1019, 'post', '2018-06-25 08:51:23', '2023-04-23 12:25:54');

