INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1005, 'Thành Cổ Loa', 'thanh-co-loa', '<p>Thành Cổ Loa là kinh đô của nhà nước Âu Lạc do <a href="https://huynhhieutravel.com/an-duong-vuong/">An Dương Vương</a> thành lập. Thành Cổ Loa được thành lập vào thế kỷ thứ 3 TCN. Hiện nay, thành Cổ Loa nằm ở xã Cổ Loa, Đông Anh, Hà Nội. Vào năm 1962 thành Cổ Loa được đưa vào danh sách di sản văn hóa quốc gia của Việt Nam. Thành gắn liền với nhiều truyền thuyết xưa, mà điển hình là truyền thuyết Trọng Thủy &#8211; Mị Châu. Ngoài ra, xét về mặt lịch sử, thành Cổ Loa mang ý nghĩa to lớn. Nơi này đánh dấu cột mốc dân tộc ta bắt đầu chuyển sang định cư và đóng đô từ vùng núi sang vùng đồng bằng. Hãy cùng Huynh Hieu Travel tìm hiểu về thành Cổ Loa nhé!</p>
<h2>Thành Cổ Loa</h2>
<p>Dời đô từ vùng núi đến đây và xây dựng nên một thành trì to lớn. <a href="https://huynhhieutravel.com/an-duong-vuong/">An Dương Vương</a> đã tìm hiểu những thuận lợi về mặt địa lý để kiến tạo nên một ngôi thành lịch sử.</p>
<p><figure id="attachment_1007" aria-describedby="caption-attachment-1007" style="width: 660px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1007" src="https://media.huynhhieutravel.com/thanh-co-loa.jpg" alt="Thành Cổ Loa" width="660" height="495"><figcaption id="caption-attachment-1007" class="wp-caption-text">Thành Cổ Loa</figcaption></figure></p>
<h3>Vị trí địa lý</h3>
<p>Thời xưa, Cổ Loa nằm ở vị trí đỉnh tam giác châu thổ sông Hồng. Nơi đây giao thương dễ dàng khi giao tiếp cả đường thủy và đường bộ. Khi nắm giữ nơi đây, người Âu Lạc sẽ bao quát cả vùng đồng bằng và kiểm soát cả vùng núi.</p>
<p>Thành Cổ Loa nằm bên con sông Hoành. Nơi giao thoa nối liền sông Hồng và sông Cầu (Con sông lớn nhất trong hệ thống sông rạch chằng chịt Thái Bình). Việc nắm giữ đường thủy cả hai con sông Hồng và sông Thái Bình mang đến lợi thế thông thương to lớn cho thành Cổ Loa. Hai con sông này gần như chiếm toàn bộ hệ thống đường thủy Bắc bộ thời bấy giờ. Nếu muốn ra biển lớn chỉ cần xuôi theo con sông Hồng. Nếu muốn đi ngược lại vùng đồng bằng Tây Bắc thì xuôi theo con sông Thái Bình.</p>
<p><figure id="attachment_1009" aria-describedby="caption-attachment-1009" style="width: 900px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1009" src="https://media.huynhhieutravel.com/thanh-co-loa3.jpg" alt="Thành Cổ Loa" width="900" height="369" srcset="https://media.huynhhieutravel.com/thanh-co-loa3.jpg 900w, https://media.huynhhieutravel.com/thanh-co-loa3-768x315.jpg 768w" sizes="(max-width: 900px) 100vw, 900px" /><figcaption id="caption-attachment-1009" class="wp-caption-text">Thành Cổ Loa</figcaption></figure></p>
<p>Mặt còn lại của thành Cổ Loa là vùng đồng bằng rộng lớn. Nơi đây bắt đầu xuất hiện nhiều xóm làng, dân chúng sống đông đúc. Kinh tế phát triển vượt bậc với đủ các loại nghề: Trồng lúa, thủ công nghiệp, đánh bắt cá,&#8230; Tuy giai đoạn trị vì của An Dương Vương chỉ khoảng 30-50 năm. Nhưng đây là giai đoạn đánh dấu sự chuyển mình của dân tộc Việt cổ. Địa lý từ vùng núi sang vùng đất đồng bằng trù phú. Không những là kinh tế tăng trưởng vượt bậc mà nền văn hóa Đông Sơn cũng rực rỡ nhất vào giai đoạn này.</p>
<h3>Giai đoạn xây dựng thành Cổ Loa</h3>
<p>Thành Cổ Loa xưa và nay có sự khác biệt. Thời gian trôi qua, với sự tác động của thiên nhiên và con người đã làm thành Cổ Loa thay đổi.</p>
<h4>Thành Cổ Loa xưa</h4>
<p>Theo sử sách xưa,&nbsp;thành được xây quanh co chín lớp, chu vi chín dặm, sâu nghìn trượng, xoáy tròn như hình ốc. Nên được gọi là Loa Thành (&#8220;loa&#8221; có nghĩa là con ốc). Thành còn có tên nôm là Chạ Chủ và nhiều tên khác như Khả Lũ (&#8220;Lũ&#8221; có nghĩa là quanh co nhiều lớp), Côn Lôn thành (ý nói thành cao như núi Côn Lôn bên Trung Quốc) hoặc Việt Vương thành (thành của vua xứ Việt), dân địa phương gọi bằng tên tiếng nôm là thành Chủ.</p>
<p>Để có đất xây thành, An Dương Vương phải cho dời dân tại chỗ đi nơi khác. Theo truyền thuyết thì làng Quậy hiện nay nguyên vốn ở tại Cổ Loa đã phải dời xuống vùng đất trũng cuối dòng sông Hoàng để An Dương Vương xây thành.</p>
<p><figure id="attachment_1010" aria-describedby="caption-attachment-1010" style="width: 556px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1010" src="https://media.huynhhieutravel.com/thanh-co-loa4.jpg" alt="Thành Cổ Loa" width="556" height="396"><figcaption id="caption-attachment-1010" class="wp-caption-text">Thành Cổ Loa</figcaption></figure></p>
<p>Thành Cổ Loa được các nhà khảo cổ học đánh giá là &#8220;tòa thành cổ nhất, quy mô lớn vào bậc nhất, cấu trúc cũng thuộc loại độc đáo nhất trong lịch sử xây dựng thành lũy của nước ta&#8221;</p>
<p>Vào thời Âu Lạc, con người chỉ mới làm quen với một ít kỹ thuật sơ khai, công cụ lao động còn rất thô thiển, ít hiệu quả, tất cả công việc đều do bàn tay người mà ra. Muốn xây được công trình với &#8220;quy mô lớn vào bậc nhất&#8221; này, phải có một số lượng khổng lồ đất đào đắp, đá kè và gốm rải. Nhà nước Âu Lạc hẳn đã phải điều động một số nhân công rất lớn để lao động trong một thời gian rất dài mới có thể hoàn thành được. Các nhà khảo cổ học cho rằng đã phải có đến hàng vạn người làm việc hàng năm cho công trình này.</p>
<p>Khi xây thành, người xưa đã biết lợi dụng tối đa và khéo léo các địa hình tự nhiên. Họ tận dụng chiều cao của các đồi, gò, đắp thêm đất cho cao hơn để xây nên hai bức tường thành phía ngoài, vì thế hai bức tường thành này có đường nét uốn lượn theo địa hình chứ không băng theo đường thẳng như bức tường thành trung tâm. Người xưa lại xây thành bên cạnh con sông Hoàng để dùng sông này vừa làm hào bảo vệ thành vừa là nguồn cung cấp nước cho toàn bộ hệ thống hào vừa là đường thủy quan trọng. Chiếc Đầm Cả rộng lớn nằm ở phía Đông cũng được tận dụng biến thành bến cảng làm nơi tụ họp cho đến cả hàng trăm thuyền bè.</p>
<p>Chất liệu chủ yếu dùng để xây thành là đất, sau đó là đá và gốm vỡ. Đá được dùng để kè cho chân thành được vững chắc. Các đoạn thành ven sông, ven đầm được kè nhiều đá hơn các đoạn khác. Đá kè là loại đá tảng lớn và đá cuội được chở tới từ các miền núi. Xen giữa đám đất đá là những lớp gốm được rải dày mỏng khác nhau, nhiều nhất là ở chân thành và rìa thành để chống sụt lở. Các cuộc khai quật khảo cổ học đã tìm thấy một số lượng gốm khổng lồ gồm ngói ống, ngói bản, đầu ngói, đinh ngói. Ngói có nhiều loại với độ nung khác nhau. Có cái được nung ở nhiệt độ thấp, có cái được nung rất cao gần như sành. Ngói được trang trí nhiều loại hoa văn ở một mặt hay hai mặt.</p>
<p>Tường thành phía ngoài được xây dựng đứng để gây khó khăn cho đối phương, còn mặt trong thì được xây thoai thoải để dễ dàng lên xuống.</p>
<h4>Thành Cổ Loa từ đời Ngô Quyền đến hiện nay.</h4>
<p>Ngô Quyền cho đóng đô ở thành Cổ Loa. Ngô Quyền đã tiến hành nhiều cải cánh khác nhau. Mà điển hình là việc tu sửa lại thành Cổ Loa thành nơi trung tâm về quân sự, kinh tế và văn hóa của cả nước. Tuy vậy&nbsp;Ngô Quyền chỉ tại vị được 6 năm, một tòa thành Cổ Loa hoàn toàn mới của triều đại nhà Ngô như ý kiến của một số nhà nghiên cứu, thật khó có điều kiện khả thi. Thành Cổ Loa trong thời gian ngắn này có lẽ chỉ được đắp thêm từng phần trên cơ sở tòa thành cũ của An Dương Vương đã được gia cố nhiều lần trong thời kỳ Bắc thuộc.</p>
<p><figure id="attachment_1011" aria-describedby="caption-attachment-1011" style="width: 1600px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1011" src="https://media.huynhhieutravel.com/thanh-co-loa5.jpg" alt="Thành Cổ Loa" width="1600" height="1060" srcset="https://media.huynhhieutravel.com/thanh-co-loa5.jpg 1600w, https://media.huynhhieutravel.com/thanh-co-loa5-768x509.jpg 768w" sizes="(max-width: 1600px) 100vw, 1600px" /><figcaption id="caption-attachment-1011" class="wp-caption-text">Thành Cổ Loa</figcaption></figure></p>
<p>Từ thời của Ngô Quyền đến nay, thành Cổ Loa đã được tu sửa và xây dựng thêm. Thành lúc ấy có 3 vòng chính, chia thành: Thành nội, thành trung và thành ngoại.</p>
<p>Chu vi vòng ngoài 8&nbsp;km, vòng giữa 6,5&nbsp;km, vòng trong 1,6&nbsp;km, diện tích trung tâm lên tới 2&nbsp;km². Thành được xây theo phương pháp đào đất đến đâu, khoét hào đến đó, thành đắp đến đâu, lũy xây đến đó. Mặt ngoài lũy, dốc thẳng đứng, mặt trong xoải để đánh vào thì khó, trong đánh ra thì dễ. Lũy cao trung bình từ 4 m-5 m, có chỗ cao đến 8 m-12 m. Chân lũy rộng 20 m-30 m, mặt lũy rộng 6 m-12 m. Khối lượng đất đào đắp ước tính 2,2 triệu mét khối.</p>
<p><strong>Thành nội</strong> hình chữ nhật, cao trung bình 5 m so với mặt đất, mặt thành rộng từ 6 m-12 m, chân rộng từ 20 m-30 m, chu vi 1.650 m và có một cửa nhìn vào tòa kiến trúc Ngự triều di quy.</p>
<p><strong>Thành trung</strong> là một vòng thành không có khuôn hình cân xứng, dài 6.500 m, nơi cao nhất là 10 m, mặt thành rộng trung bình 10 m, có bốn cửa ở các hướng cống song, bắc, tây bắc và tây nam, trong đó cửa đông ăn thông với sông Hồng.</p>
<p><strong>Thành ngoại</strong> cũng không có hình dáng rõ ràng, dài hơn 8.000m, cao trung bình 3 m-4 m (có chỗ tới hơn 8 m).</p>
<p>Mỗi vòng thành đều có hào nước bao quanh bên ngoài, hào rộng trung bình từ 10m đến 30m, có chỗ còn rộng hơn. Các vòng hào đều thông với nhau và thông với sông Hoàng. Sự kết hợp của sông, hào và tường thành không có hình dạng nhất định, khiến thành như một mê cung, là một khu quân sự vừa thuận lợi cho tấn công vừa tốt cho phòng thủ.</p>
<p>Sông Hoàng được dùng làm hào thiên nhiên cho thành Ngoại ở về phía Tây Nam và Nam. Phần hào còn lại được đào sát chân tường thành từ gò Cột Cờ đến Đầm Cả. Con hào này nối với hào của thành Trung ở Đầm Cả và Xóm Mít, chảy qua cửa Cống Song nối với năm con lạch có hình dáng như bàn tay xòe, và với một nhánh của con lạch này, nước chảy thông vào vòng hào của thành Nội.</p>
<p>Thuyền bè đi lại dễ dàng trên ba vòng hào để đến trú đậu ở Đầm Cả hoặc ra sông Hoàng và từ đó có thể tỏa đi khắp nơi. Theo truyền thuyết,Thục Phán An Dương Vương thường dùng thuyền đi khắp các hào rồi ra sông Hồng.</p>
<h3>Những giá trị thành Cổ Loa mang lại</h3>
<p>Trong cấu trúc thành Cổ Loa khi xây dưng, thành Cổ Loa tận dụng lợi thế thiên nhiên khá nhiều. Vì vậy, trên những gò đất cao và dài là những ụ, lũy được xây dựng để canh gác. Một số lũy như vậy được dân đặt tên như Đống Dân, Đống Chuông, Đống Bắn&#8230;</p>
<p>Về mặt quân sự, thành Cổ Loa thể hiện sự sáng tạo độc đáo của người Việt cổ trong công cuộc giữ nước và chống ngoại xâm. Với các bức thành kiên cố, với hào sâu rộng cùng các ụ, lũy, Cổ Loa là một căn cứ phòng thủ vững chắc để bảo vệ nhà vua, triều đình và kinh đô. Đồng thời là một căn cứ kết hợp hài hòa thủy binh cùng bộ binh. Nhờ ba vòng hào thông nhau dễ dàng, thủy binh có thể phối hợp cùng bộ binh để vận động trên bộ cũng như trên nước khi tác chiến.</p>
<p><figure id="attachment_1008" aria-describedby="caption-attachment-1008" style="width: 450px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1008" src="https://media.huynhhieutravel.com/thanh-co-loa2.jpg" alt="Thành Cổ Loa" width="450" height="338"><figcaption id="caption-attachment-1008" class="wp-caption-text">Thành Cổ Loa</figcaption></figure></p>
<p>Về mặt xã hội, với sự phân bố từng khu cư trú cho vua, quan, binh lính, thành Cổ Loa là một chứng cứ về sự phân hóa của xã hội thời ấy. Thời kỳ này, vua quan không những đã tách khỏi dân chúng mà còn phải được bảo vệ chặt chẽ, sống gần như cô lập hẳn với cuộc sống bình thường. Xã hội đã có giai cấp rõ ràng và xã hội có sự phân hóa giàu nghèo rõ ràng hơn thời Vua Hùng.</p>
<p>Về mặt văn hóa, là một tòa thành cổ nhất còn để lại dấu tích, Cổ Loa trở thành một di sản văn hóa, một bằng chứng về sự sáng tạo, về trình độ kỹ thuật cũng như văn hóa của người Việt Cổ. Đá kè chân thành, gốm rải rìa thành, hào nước quanh co, ụ lũy phức tạp, hỏa hồi chắc chắn và nhất là địa hình hiểm trở ngoằn ngoèo, tất cả những điều làm chứng nghệ thuật và văn hóa thời An Dương Vương. Hàng năm, vào ngày 6 tháng giêng âm lịch, cư dân Cổ Loa tổ chức một lễ trang trọng để tưởng nhớ đến những người xưa đã có công xây thành, và nhất là để ghi ơn An Dương Vương.</p>
<p>Hiện nay Cổ Loa là một trong 21 khu du lịch quốc gia Việt Nam, và vào ngày 27/9/2012 di tích lịch sử kiến trúc nghệ thuật và khảo cổ Cổ Loa được Thủ tướng Chính phủ quyết định xếp hạng di tích quốc gia đặc biệt.</p>
<h3>Thành Cổ Loa hiện nay và quy hoạch tương lai</h3>
<p>Trong những năm gần đây thành Cổ Loa bắt đầu khoác lên mình một diện mạo mới hơn. Các dự án quy hoạch và tu sửa thành Cổ Loa đang được phát triển thêm nhiều hơn.&nbsp;Một số dự án tu bổ tôn tạo trong khu vực Cổ Loa như: Am Mỵ Châu, đình Ngự triều di quy, đền An Dương Vương, đình-chùa Mạch Tràng, Giếng Ngọc, khảo cổ học Mắt Rồng, Bãi Mèn, Đồng Vông… cùng một số công trình giao thông đã hoàn thành như đường vào cửa Tây, cầu qua sông Hoàng, bãi để xe và một số hạng mục phụ trợ.</p>
<p>Xã Cổ Loa hiện có 14 thôn, xóm trong đó 11 xóm ở trên, trong hoặc giữa các vòng thành. Điều này đã tạo nên sự khác biệt của Cổ Loa so với các khu di tích khác. Khu di tích này vẫn cộng động cho người dân sống xen kẻ bên trong. Cũng từ đây nảy sinh những khó khăn trong công tác bảo tồn. Theo thống kê năm 1997, số hộ dân trên mặt thành và hào là 330 hộ. Theo thống kê năm 2005 của Văn phòng Tư vấn và Chuyển giao công nghệ xây dựng – trường Đại học Kiến trúc Hà Nội(đơn vị lập báo cáo đầu tư tu bổ tôn tạo khu di tích Cổ Loa) thì tổng số dân trên đất thành là 394 hộ, trong đó khu thành Nội có 119 hộ. Sự tăng hộ này là do dân số tăng tự nhiên trong các xóm, làng (tỉ lệ tăng tự nhiên ở Cổ Loa là 1,33%/năm). Số nhà mới xây dựng vì thế cũng tăng lên, hầu hết là xây dựng trên đất thổ cư đã được cấp giấy phép quyền sử dụng đất.</p>
<p>Những việc đó tạo nên nhiều tổn hại cho di tích Thành Cổ Loa. Nhưng hiện đang được khắc phục dần. Những kế hoạch bảo tồn chi tiết đã được thông qua. Hy vọng thành Cổ Loa sẽ giữ lại những nét cổ xưa độc đáo làm nên một di tích cấp quốc gia.</p>
', 'Thành Cổ Loa là kinh đô của nhà nước Âu Lạc do An Dương Vương thành lập. Thành Cổ Loa được thành lập vào thế kỷ thứ 3 TCN. Hiện nay, thành Cổ Loa nằm ở xã Cổ Loa, Đông Anh, Hà Nội. Vào năm 1962 thành Cổ Loa được đưa vào danh sách di [&hellip;]', 1007, 'post', '2018-06-24 07:56:02', '2023-04-23 12:33:55');

