INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1006, 'Sự tích thành Cổ Loa', 'su-tich-thanh-co-loa', '<p>Thành Cổ Loa được xây dựng dưới thời <a href="https://huynhhieutravel.com/an-duong-vuong/">An Dương Vương</a>. Ngôi thành mang ý nghĩa lịch sử to lớn về mặt quân sự cũng như văn hóa. Nó đánh dấu cột mốc quan trọng khi tộc Việt cổ chuyển từ thói quen sống ở miền núi sang ở đồng bằng. Sự tích xây dựng thành Cổ Loa có nhiều dị bản khác nhau. Nhưng đây là một bản được xem là đầy đủ và chân thật nhất trong góc độ truyền thuyết.</p>
<h2>Sự Tích Thành Cổ Loa Trong Dân Gian</h2>
<p>Khi đã chiếm được đất Văn Lang, <a href="https://huynhhieutravel.com/an-duong-vuong/">An Dương Vương</a> đổi tên nước là Âu Lạc, đóng đô ở Phong Khê.</p>
<p>Khu đất chọn để đắp thành là một quả đồi đất rắn như đá. Ðám đông người hì hục đào đất, khuân đất hết ngày nọ sang ngày kia, tòa thành cao dần.</p>
<p><a href="https://huynhhieutravel.com/an-duong-vuong/">An Dương Vương</a> cùng đoàn tùy tùng đến xem rất lấy làm hài lòng, cho là một tòa thành có thể đứng vững muôn đời, sấm sét không lay chuyển, mưa bão không làm sạt được, và quân giặc cũng không thể phá nổi.</p>
<h3>Gian nan xây tường thành</h3>
<p>Nhưng một đêm cả bức tường thành quanh co đều đổ sập xuống như đất bằng. Vua An Dương Vương đến xem rất lấy làm tức giận. Ngài hỏi dò dân chúng gần đó, họ kể lại: Ban đêm họ nghe thấy những bước chân rầm rập ở các khắp ngã kéo đến với những tiếng xì xào có thể là ma quỉ. Người đâu mà lại đông đến thế ! Họ sợ quá nên không dám nhìn ra. Rồi họ lại nghe những tiếng đổ ầm ầm như sấm dậy.</p>
<p>An Dương Vương sai các tướng lãnh đốc thúc đắp lại thành cho kỳ được. Ðám người hăng hái đắp lại không ngừng. Tường thành mỗi ngày một cao dần và lại cao như tường thành cũ. Nhưng rồi một đêm cả dãy tường thành lại sập xuống như đất bằng. An Dương Vương sai người đi hỏi dân chúng ở gần đó thì họ lại nói như trước. Ban đêm họ cũng nghe thấy những bước chân rầm rập như thiên binh vạn mã trẩy qua rồi lại những tiềng huỳnh huỵch tiếp đến những tiếng ầm ầm như sấm động.</p>
<p><figure id="attachment_1007" aria-describedby="caption-attachment-1007" style="width: 660px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1007" src="https://media.huynhhieutravel.com/thanh-co-loa.jpg" alt="Thành Cổ Loa" width="660" height="495"><figcaption id="caption-attachment-1007" class="wp-caption-text">Thành Cổ Loa nhìn từ trên cao</figcaption></figure></p>
<p>An Dương Vương lại xem chỗ địa thành để cầu trời phù hộ mình đắp cho xong tòa thành. Vua đi vòng quanh chân tường vừa đi vừa suy nghĩ. Ðột nhiên vua thấy một ông già râu tóc bạc từ phía xa đi lại. Ðến gần An Dương Vương ông tự xưng mình là thổ thần của vùng đất này, nói với vua rằng:</p>
<p>– Nhà vua đừng lo, sáng mai nhà vua ra đợi ở bờ sông sẽ có sứ giả Thanh Giang đến giúp nhà vua đắp thành.</p>
<p>Nói xong ông già biến mất.</p>
<h3>Thần Kim Qui xuất hiện</h3>
<p>Hôm sau mới tờ mờ sáng, An Dương Vương đã ra tận bờ sông để đợi Giang sứ. Vừa bắt đầu tan sương thì có một con rùa vàng rất lớn nổi lên mặt sông từ phía Ðông bơi vào bờ đến gần nhà vua, rùa tự xưng mình là thần Kim Quy sứ giả của vua Thủy Tề. An Dương Vương sai đặt Giang sứ lên một chiếc mâm vàng và khiêng vào cung.</p>
<p>Vua hỏi kế đắp thành, thần Kim Quy bảo rằng:</p>
<p>&#8211; Ở núi Thất Diệu có một con gà trắng sống lâu năm thành tinh có phép biến hoá khôn lường. Nó thường hãm hại khách qua đường và khách ngủ ở quán trọ trong vùng này. Các vua thời trước cùng bọn nhạc công chết đi đều chôn ở núi Thất Diệu, những u hồn ấy từ lâu không tan lẩn khuất trong khe đá ở hang sâu. Những u hồn ấy có thù với nhà vua nên đêm thanh vắng họp thành từng đàn từng lũ đến xúi dục con tinh gà trắng phá thành đang xây của nhà vua. Con tinh gà trắng đã dẫn những u hồn ấy đến chân thành dùng phép ma phá đổ tường thành rồi gần sáng lại bay về núi. Con tinh gà trắng có tiền duyên với con gái lão chủ quán gần chân núi nên hay hiện hình làm khách bộ hành ghé vào nhà lão khi thì nhập vào con gái lão khi thì nhập vào con gà trắng của lão. Muốn đắp cho được thành, trước hết phải trừ cho tiệt giống yêu ma và giết đứa con gái cùng con gà trắng của lão chủ quán kia đi.</p>
<p><figure id="attachment_1010" aria-describedby="caption-attachment-1010" style="width: 556px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1010 size-full" src="https://media.huynhhieutravel.com/thanh-co-loa4.jpg" alt="Thành Cổ Loa thời xưa" width="556" height="396"><figcaption id="caption-attachment-1010" class="wp-caption-text">Thành Cổ Loa thời xưa</figcaption></figure></p>
<p>Nghe lời thần mách bảo, Vua sai mấy viên tướng đem quân vào rừng mai phục rồi vua cải trang cùng thần Kim Quy giả làm khách bộ hành đến quán xin ngủ trọ. Chủ quán từ chối lấy cớ là trong núi có nhiều yêu quái hay làm hại khách đi đường. Nhưng An Dương Vương và thần Kim Quy nhất định xin ở. Chủ quán phải chiều theo ý hai người.</p>
<p>Ðêm đêm An Dương Vương nghe thấy những bước chân rầm rập ở ngoài. Những bước chân từ khắp các ngả đi lại rộn ràng rồi thốt nhiên có bàn tay rất mạnh đập vào cái phên nhà lão chủ quán tiếp đến tiếng gọi người con gái lão. Thần Kim Quy lên tiếng nạt nộ, tiếng ngoài im ngay. Những tiếng chân bước cũng xa dần.</p>
<p><figure id="attachment_1008" aria-describedby="caption-attachment-1008" style="width: 450px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1008" src="https://media.huynhhieutravel.com/thanh-co-loa2.jpg" alt="Thành Cổ Loa" width="450" height="338"><figcaption id="caption-attachment-1008" class="wp-caption-text">Thành Cổ Loa</figcaption></figure></p>
<p>Gần sáng lại có những tiếng chân rầm rập ở ngoài, thần Kim Quy bảo An Dương Vương mở cửa phên ra gọi quân mai phuc đuổi theo đám yêu tinh đang rút lui về Thất Diệu, quân lính vừa đuổi vừa giương nỏ bắn theo. Cứ một loạt tên bay đi là lại nổi lên những tiếng ma kêu quỷ khóc rùng rợn.</p>
<p>Tiếng rên rỉ khóc than mỗi lúc một thưa dần. Ðến khi mặt trời mọc thì yêu khí tan. Quân lính của An Dương Vương đào được rất nhiều hài cốt và nhạc khí cổ trong các hang núi, họ chất thành từng đống cao đốt đi rồi tro than đổ xuống suối cho tan hẳn oan hồn.</p>
<h3>Thành công trừ yêu</h3>
<p>An Dương Vương và thần Kim Quy trở về quán trọ bảo chủ quán hiến cho mình con gà trắng để tạ trời đất. Gà vừa bị cắt tiết thì con gái chủ quán cũng lăn ra chết. Giữa lúc ấy có một con chim tứ trong nhà bay vụt ra, thần Kim Quy biết đó là con yêu tinh đã tìm đường chạy trốn, liền tung phép giết chết.</p>
<p><figure id="attachment_1009" aria-describedby="caption-attachment-1009" style="width: 900px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1009 size-full" src="https://media.huynhhieutravel.com/thanh-co-loa3.jpg" alt="Thành Cổ Loa ngày nay" width="900" height="369" srcset="https://media.huynhhieutravel.com/thanh-co-loa3.jpg 900w, https://media.huynhhieutravel.com/thanh-co-loa3-768x315.jpg 768w" sizes="(max-width: 900px) 100vw, 900px" /><figcaption id="caption-attachment-1009" class="wp-caption-text">Thành Cổ Loa ngày nay</figcaption></figure></p>
<p>Yêu ma đã trừ xong, thần Kim Quy lại hiện nguyên hình là con rùa vàng rất lớn. Thần rút một cái móng của mình trao cho An Dương Vương, dặn rằng:</p>
<p>&#8211; Nhà vua giữ lấy móng chân này để làm lẫy nỏ. Khi có giặc thì đem ra bắn, một phát có thể giết được hàng nghìn quân giặc.</p>
<p>Nói xong, thần biến mất, nhờ có thần Kim Quy trừ hết yêu ma. An Dương Vương ra lệnh cho quân lính và nhân dân xây lại thành. Chẳng bao lâu tòa thành đắp xong, rộng tới ngàn trượng, vừa dầy vừa cao xoáy vòng như hình con ốc, nên gọi là Loa thành.</p>
', 'Thành Cổ Loa được xây dựng dưới thời An Dương Vương. Ngôi thành mang ý nghĩa lịch sử to lớn về mặt quân sự cũng như văn hóa. Nó đánh dấu cột mốc quan trọng khi tộc Việt cổ chuyển từ thói quen sống ở miền núi sang ở đồng bằng. Sự tích xây dựng [&hellip;]', 1011, 'post', '2018-06-24 07:29:30', '2023-04-23 12:33:56');

