INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (977, 'Kinh Dương Vương &#8211; Ông Là Ai?', 'kinh-duong-vuong', '<p>Kinh Dương Vương theo tục truyền là cha của Lạc Long Quân và là ông nội của vua Hùng &#8211; Thủy tổ của dân tộc Việt Nam. Vậy Kinh Dương Vương thật sự là ai?</p>
<h2>Kinh Dương Vương Là Ai?</h2>
<p>Kinh Dương Vương (2919 TCN &#8211; 2792 TCN) thuộc dòng dõi của Thần Nông. Ông là cha của Lạc Long Quân và là ông nội của vua Hùng. Chúng ta cùng xem gia phả nguồn gốc dân tộc Việt.</p>
<p><figure id="attachment_978" aria-describedby="caption-attachment-978" style="width: 702px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-978" src="https://media.huynhhieutravel.com/gia-pha-dan-toc-Viet-Nam.jpg" alt="Gia phả dân tộc Việt" width="702" height="526"><figcaption id="caption-attachment-978" class="wp-caption-text"><em>Gia phả dân tộc Việt</em></figcaption></figure></p>
<p>Theo sử sách ghi lại, tên húy ông là Lộc Tục. Ông là người dựng nên nhà nước sơ khai tên là Xích Quỷ. Sau đó ông truyền ngôi lại cho người con trai là Lạc Long Quân. Cũng có sách sử cho rằng ông là thủ lĩnh của một bộ lạc lớn. Ông có công tập hợp lại các bộ lạc và thống nhất lại tộc người Lạc Việt.</p>
<p>Trong Đại Việt Sử Ký Toàn Thư viết rằng Kinh Dương Vương xuất thân từ phương Bắc. Ông là con của Đế Minh và Vụ Tiên. Sách sử không ghi rõ ông làm vua vào năm nào. Nhiều nhà sử học thời đó cũng không xác định rõ nên cho đó là kỷ Hồng Bàng. Một kỷ nguyên của họ Hồng Bàng lập quốc.</p>
<h3>Tại sao Hùng Vương là tổ chứ không phải Lạc Long Quân hay Kinh Dương Vương của dân tộc Việt Nam?</h3>
<p>Theo truyền thuyết thì Kinh Dương Vương là người sinh ra Lạc Long Quân. Và là ông nội của Hùng Vương. Và rõ ràng, những luận cứ đó đều bắt nguồn từ &#8216;TRUYỀN THUYẾT&#8221;. Nên các nhà sử học đều không lấy nó làm căn cứ xác định Tổ cho dân tộc ta.</p>
<p>“Trong Đại Việt sử kí toàn thư, Ngô Sĩ Liên đã xếp vào phần ngoại kỷ chứ không phải lịch sử chính thống. Vì đây là những nhân vật thần thoại chứ không phải nhân vật lịch sử, kể ra mang tính biểu tượng, để giải thích ra cuội nguồn dân tộc. Chính vì thế, chúng ta không nên hiểu như phả hệ của một dòng họ”, PGS.TS. Bùi Quang Thanh nói.</p>
<h3>Ảnh Hưởng Của Trung Quốc Đến Các Nước Lân Cận</h3>
<p>Ngoài ra chúng ta cũng phải nói đến truyền thuyết nguồn gốc các dân tộc Đông Nam Á. Đa phần đều có liên quan đến thủy tổ Trung Quốc. Tại sao lại vậy? Đa phần trước đây, các nước gần Trung Quốc đều là chư hầu. Trung Quốc vẫn là một đất nước lớn bao trùm các nước khác. Ở Việt Nam, đến năm 938 chúng ta mới có một vị xưng Vương đầu tiên là Ngô Quyền, cũng không phải là hoàng đế.</p>
<p>Từ đó ta thấy ảnh hưởng Trung Quốc là lớn đến thế nào đến các nước lân cận. Và việc lấy thủy tổ, những dân tộc xuất thân dính dáng đến quốc gia to lớn Trung Quốc đều là một vinh hạnh. Không những là Việt Nam mà cả Thái Lan. Theo phả hệ các nước đó đều có một chút liên quan đến Trung Quốc.</p>
<p>Và nếu truy nguồn gốc sâu hơn Kinh Dương Vương và sâu xa hơn nữa làm thủy tổ. Điều đó thật là bất khả thi. Nên chúng ta lấy một sự chính xác và nguyên nhân tốt nhất làm thủy tổ. Vua Hùng là người đầu tiên xác lập nên một nhà nước &#8211; nước Văn Lang chính thống. Người mới đích thật là thủy tổ của nước Việt Nam.</p>
<h3>Xuất Hiện Từ Truyền Thuyết Của Trung Quốc?</h3>
<p>Đề cập đến vấn đề &#8220;thấy sang bắt quàng làm họ&#8221; của dân tộc xưa với Trung Quốc. Ta tìm hiểu rõ hơn tại sao lại xuất hiện nhân vật mang tên Kinh Dương Vương này. Nhân vật Kinh Dương Vương bắt đầu xuất hiện từ Đại Việt Sử Ký Toàn Thư của Ngô Sĩ Liên. Cuốn toàn thư này có ảnh hưởng rất lớn đến các bút ký về lịch sử khác của các sử gia các triều đại Việt Nam sau này.</p>
<p>Nhưng lần về sâu xa hơn, các học giả đều thống nhất cho rằng, truyện Kinh Dương Vương có sự sao chép từ tiểu thuyết&nbsp;<em>Liễu Nghị truyện</em>(柳毅傳). Cuốn tiểu thuyết do Lý Triều Uy sáng tác vào đời Đường. Ngô Sĩ Liên đã tình cờ đem một số chi tiết của truyện Liễu Nghị để ghép với các huyền thoại khác như Lạc Long Quân &#8211; Âu Cơ. Và coi đó như nguồn gốc khởi đầu cho sự xuất hiện của Hùng Vương &#8211; triều đại mà người Việt ngày nay coi như lịch sử đích thực của mình.</p>
<h3>Nhận Định Của Các Sử Gia Khác</h3>
<p>Nhận định của Ngô Thì Sĩ trong&nbsp;<em>Đại Việt sử kí Tiền biên</em>. Ông viết: “Nay xét phần Ngoại kỉ chép: Năm Nhâm Tuất thì bắt đầu Giáp Tí là năm nào? Ghi chép tên húy Kinh Dương Vương, Lạc Long Quân sao riêng lược bỏ Hùng Vương? Thời Ngũ Đế trở về trước thì chưa từng gọi là vương. Xích Quỷ là tên nào, mà lại để làm tên nước.</p>
<p>Một loạt hoang đường càn rỡ đều là đáng bỏ đi. Cái lỗi ấy lại tại kẻ hiếu sự thấy trong&nbsp;<em>Liễu Nghị truyền thư</em>. Trong truyện nói con gái vua Động Đình gả cho con thứ của Kinh Xuyên Vương, tưởng càn Kinh Xuyên là Kinh Dương. Đã có vợ chồng thì có cha con, vua tôi, nhân đó mà thêu dệt thành văn, cốt cho đủ số đời vua, nhà làm sử theo đó mà chọn dùng, và cho đó là sự thực. Phàm những chuyện lấy từ&nbsp;<em>Lĩnh Nam chích quái, Việt điện u linh</em>, cũng như Bắc sử lấy ở&nbsp;<em>Kinh Nam Hoa</em>&nbsp;và thiên&nbsp;<em>Hồng Liệt</em>&nbsp;đấy&#8221;.</p>
<p>Qua thời kỳ lịch sử, nhiều truyền thuyết và câu chuyện dân gian ra đời. Những điều ấy được sáng tạo ra nhưng không ai ngờ về sau càng chảy quay nhiều thời kỳ lịch sử. Những câu chuyện truyền miệng dần trở thành những sự thật không ai thay đổi được.</p>
<h3>Ta Cũng Không Lãng Quên Ông Nội Và Cha Của Vua Hùng</h3>
<p>Tuy rằng việc xác định thủy tổ còn chưa rõ ràng. Nhưng chúng ta cũng không bỏ quên công lao của Kinh Dương Vương. Nhiều đình thờ tương truyền bắt đầu có từ thời nhà Đinh. Di tích cổ nhất thời đó được tìm thấy ở tỉnh Thái Bình.</p>
<p>Ngoài ra, Lăng và đền thờ của Kinh Dương Vương ở Bắc Ninh được nhiều đời triều đại vua phong kiến Việt Nam thờ phụng. Đến bây giờ ở Bắc Ninh vẫn tổ chức lễ hội thờ cúng Kinh Dương Vương hàng năm. Tên ông lấy làm tên đường nhiều tỉnh thành ở nước ta, đặc biệt thành phố Hồ Chí Minh cũng có tên đường của ông.</p>
', 'Kinh Dương Vương theo tục truyền là cha của Lạc Long Quân và là ông nội của vua Hùng &#8211; Thủy tổ của dân tộc Việt Nam. Vậy Kinh Dương Vương thật sự là ai? Kinh Dương Vương Là Ai? Kinh Dương Vương (2919 TCN &#8211; 2792 TCN) thuộc dòng dõi của Thần Nông. Ông [&hellip;]', 979, 'post', '2018-06-18 09:44:52', '2023-04-23 12:34:01');

