INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (931, 'Infographic Lịch Sử Việt Nam', 'infographic-lich-su-viet-nam', '<p>Infographic lịch sử Việt Nam được tóm tắt đơn giản và dễ hiểu. 4000 năm lịch sử văn hiến Việt Nam được tóm tắt ngắn gọn và dễ hiểu qua hình ảnh Infographic.</p>
<h2>Infographic Lịch Sử Việt Nam</h2>
<p>Lịch sử Việt Nam trải qua hơn 4.000 năm văn hiến với nhiều biến cố và những sự kiện khác nhau. Hãy cùng Huynh Hieu Travel nhìn lại bảng tóm tắt lịch sử Việt Nam qua các thời kỳ.</p>
<p>Mọi thông tin góp ý xin vui lòng để lại comment hoặc liên hệ với tôi qua email: huynhtronghieu1911@gmail.com</p>
<p><figure id="attachment_937" aria-describedby="caption-attachment-937" style="width: 1200px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-937" src="https://media.huynhhieutravel.com/Lịch-Sử-Việt-Nam.jpg" alt="Infographic Lịch Sử Việt Nam" width="1200" height="8992" srcset="https://media.huynhhieutravel.com/Lịch-Sử-Việt-Nam.jpg 1200w, https://media.huynhhieutravel.com/Lịch-Sử-Việt-Nam-768x5755.jpg 768w" sizes="(max-width: 1200px) 100vw, 1200px" /><figcaption id="caption-attachment-937" class="wp-caption-text">Infographic Lịch Sử Việt Nam</figcaption></figure></p>
<h3>Lịch Sử Việt Nam Qua Nhiều Đời Vua</h3>
<p>Infographic Lịch sử Việt Nam từ thời dựng nước của vua Hùng năm 2879 TCN đến năm 207 TCN. Sau đó đến thời kỳ Bắc thuộc hơn 1000 năm lịch sử từ 207 TCN đến năm 906. Tiếp theo đến thời kỳ bước đầu tự chủ của các nhà Khúc &#8211; Ngô &#8211; Đinh &#8211; Tiền Lê. Và sự huy hoàng của nhà Lý từ năm 1010 đến năm 1225. Nhà Trần sau đó tiếp nối từ năm 1225 đến năm 1400. Sau đó trải qua giai đoạn nhà Hồ ngắn ngủi từ năm 1400 đến năm 1428. Tiếp theo nhà Hậu Lê bắt đầu triều đại từ năm 1428 đến năm 1527.</p>
<p>Và nhà Mạc và phân chia Bắc Nam từ năm 1527 đến năm 1592. Sự phân liệt của Trịnh và Nguyễn từ năm 1600 đến năm 1777 kết thúc bởi triều đại ngắn ngủi của Tây Sơn từ năm 1771 đến năm 1802. Nhà Nguyễn là triều đại phong kiến cuối cùng của Việt Nam kéo dài từ năm 1802 đến năm 1945. Sau đó là các giai đoạn chống thực dân Pháp (năm 1945-1954). Giai đoạn Vietnam War là từ năm 1954 đến năm 1975 thì kết thúc.</p>
<p>Lịch sử Việt Nam trải qua nhiều biến cố và thăng trầm. Những lần giặc phương Bắc hay phương Tây có thể chiếm Việt Nam một thời gian. Dù dài hay ngắn thì đều bị tinh thần bất khuất của người dân Việt Nam đẩy lùi.</p>
', 'Infographic lịch sử Việt Nam được tóm tắt đơn giản và dễ hiểu. 4000 năm lịch sử văn hiến Việt Nam được tóm tắt ngắn gọn và dễ hiểu qua hình ảnh Infographic. Infographic Lịch Sử Việt Nam Lịch sử Việt Nam trải qua hơn 4.000 năm văn hiến với nhiều biến cố và những [&hellip;]', 934, 'post', '2018-06-15 12:14:21', '2023-04-23 12:34:02');

